//! Replay of the original `FSceneNode::ComputeRenderCoords(Location, Rotation)` (UnCamera.cpp:327-342,
//! which then runs ComputeRenderSize) against `fixtures/camera_render_coords.txt`, generated by
//! `Build/camera_fixture_harness/gen_camera.sh`. Every output float is compared bit-for-bit.
//!
//! The non-ortho path reads `hp2_core::math::VIEW_COORDS`/`sin_tab_inline`/`cos_tab_inline`
//! directly (no FFI hook); the persp branch in `ComputeRenderSize` reads `MaintainVerticalFOV`
//! from a real `UClient` backing the viewport's `outer` pointer.

use std::collections::HashMap;
use std::ffi::c_void;
use std::sync::atomic::{AtomicUsize, Ordering};

use hp2_abi::engine::generated::{APlayerPawn, FRotator, FSceneNode, UClient, UViewport};
use hp2_abi::{FCoords, FVector};
use hp2_engine::camera::{CameraServices, compute_render_coords};

const FIXTURE: &str = include_str!("fixtures/camera_render_coords.txt");
const CASES: usize = 48;
const OUT_WORDS: usize = 46;

static SET_SCENE_CALLS: AtomicUsize = AtomicUsize::new(0);

unsafe extern "C" fn record_set_scene(_render_dev: *mut c_void, _frame: *mut c_void) {
    SET_SCENE_CALLS.fetch_add(1, Ordering::SeqCst);
}

/// Fail-fast filler for every other services entry; compute_render_coords must never reach it.
unsafe extern "C" fn unexpected_service() {
    panic!("compute_render_coords reached an unexpected CameraServices entry");
}

fn services() -> CameraServices {
    const WORDS: usize = std::mem::size_of::<CameraServices>() / std::mem::size_of::<usize>();
    let filler = unexpected_service as unsafe extern "C" fn() as usize;
    let table: [usize; WORDS] = [filler; WORDS];
    let mut svc: CameraServices = unsafe { std::mem::transmute(table) };
    svc.render_dev_set_scene_node = checked_render_dev_set_scene_node;
    svc.frame_compute_render_size = replay_compute_render_size;
    svc
}

fn hex_f32(s: &str) -> f32 {
    f32::from_bits(u32::from_str_radix(s, 16).expect("hex float bits"))
}

fn flat(c: &FCoords) -> [f32; 12] {
    [
        c.origin.x, c.origin.y, c.origin.z, c.x_axis.x, c.x_axis.y, c.x_axis.z, c.y_axis.x,
        c.y_axis.y, c.y_axis.z, c.z_axis.x, c.z_axis.y, c.z_axis.z,
    ]
}

struct Case {
    idx: usize,
    x: i32,
    y: i32,
    map: i32,
    maintain: i32,
    fov: f32,
    zoom: f32,
    loc: FVector,
    rot: FRotator,
}

fn parse_case(line: &str) -> Case {
    let mut it = line.split_whitespace();
    assert_eq!(it.next(), Some("case"));
    assert_eq!(it.next(), Some("render_coords"));
    let idx: usize = it.next().expect("idx").parse().expect("idx parses");
    let kv: HashMap<&str, &str> = it.map(|t| t.split_once('=').expect("key=value")).collect();
    let loc: Vec<f32> = kv["loc"].split(',').map(hex_f32).collect();
    let rot: Vec<i32> = kv["rot"]
        .split(',')
        .map(|r| r.parse().expect("rot"))
        .collect();
    Case {
        idx,
        x: kv["x"].parse().expect("x"),
        y: kv["y"].parse().expect("y"),
        map: kv["map"].parse().expect("map"),
        maintain: kv["maintain"].parse().expect("maintain"),
        fov: hex_f32(kv["fov"]),
        zoom: hex_f32(kv["zoom"]),
        loc: FVector {
            x: loc[0],
            y: loc[1],
            z: loc[2],
        },
        rot: FRotator {
            pitch: rot[0],
            yaw: rot[1],
            roll: rot[2],
        },
    }
}

/// Runs one case; returns (coords words, uncoords words, 46 output words).
fn run_case(svc: &CameraServices, c: &Case) -> ([u32; 12], [u32; 12], Vec<u32>) {
    let mut actor: APlayerPawn = unsafe { std::mem::zeroed() };
    actor.rend_map = c.map;
    actor.base.fov_angle = c.fov;
    actor.base.ortho_zoom = c.zoom;
    let mut vp: UViewport = unsafe { std::mem::zeroed() };
    let mut render_dev = 0u8;
    vp.actor = (&mut actor as *mut APlayerPawn).cast();
    vp.ren_dev = (&mut render_dev as *mut u8).cast();
    let mut client: UClient = unsafe { std::mem::zeroed() };
    client.set_maintain_vertical_fov(c.maintain != 0);
    vp.outer = (&mut client as *mut UClient).cast();
    let mut node: FSceneNode = unsafe { std::mem::zeroed() };
    node.viewport = (&mut vp as *mut UViewport).cast();
    node.x = c.x;
    node.y = c.y;
    SET_SCENE_CALLS.store(0, Ordering::SeqCst);
    let frame: *mut FSceneNode = &mut node;
    unsafe { compute_render_coords(svc, frame, c.loc, c.rot).expect("checked replay callback") };
    assert_eq!(SET_SCENE_CALLS.load(Ordering::SeqCst), 1, "case {}", c.idx);

    let n = &node;
    let coords = flat(&n.coords).map(f32::to_bits);
    let uc = flat(&n.uncoords).map(f32::to_bits);
    let mut out: Vec<f32> = Vec::with_capacity(OUT_WORDS);
    out.extend([
        n.fx,
        n.fy,
        n.fx2,
        n.fy2,
        n.fx15,
        n.fy15,
        n.effective_fov_angle,
    ]);
    out.extend([n.proj.x, n.proj.y, n.proj.z]);
    out.extend([n.r_proj.x, n.r_proj.y, n.r_proj.z]);
    out.extend([n.zoom, n.prj_xm, n.prj_xp, n.prj_ym, n.prj_yp]);
    out.extend(n.view_sides.iter().flat_map(|v| [v.x, v.y, v.z]));
    out.extend(n.view_planes.iter().flat_map(|p| [p.x, p.y, p.z, p.w]));
    assert_eq!(out.len(), OUT_WORDS);
    (coords, uc, out.into_iter().map(f32::to_bits).collect())
}

fn words(line: &str, label: &str) -> Vec<u32> {
    let rest = line
        .strip_prefix(label)
        .unwrap_or_else(|| panic!("want {label}: {line}"));
    rest.split(|c: char| c == ',' || c.is_whitespace())
        .filter(|w| !w.is_empty())
        .map(|w| u32::from_str_radix(w, 16).expect("hex word"))
        .collect()
}

#[test]
fn compute_render_coords_matches_original() {
    let lines: Vec<&str> = FIXTURE.lines().collect();
    assert_eq!(lines.len(), CASES * 5, "record count");
    let svc = services();
    for rec in lines.chunks(5) {
        let c = parse_case(rec[0]);
        let want_coords = words(rec[1], "coords ");
        let want_uc = words(rec[2], "uc ");
        let want_out = words(rec[3], "out ");
        assert_eq!(rec[4], "setscene 1", "case {}", c.idx);
        assert_eq!(want_coords.len(), 12, "case {} coords width", c.idx);
        assert_eq!(want_uc.len(), 12, "case {} uc width", c.idx);
        assert_eq!(want_out.len(), OUT_WORDS, "case {} out width", c.idx);

        let (coords, uc, out) = run_case(&svc, &c);
        for k in 0..12 {
            assert_eq!(coords[k], want_coords[k], "case {} coords word {k}", c.idx);
            assert_eq!(uc[k], want_uc[k], "case {} uc word {k}", c.idx);
        }
        for (i, (g, w)) in out.iter().zip(&want_out).enumerate() {
            assert_eq!(g, w, "case {} out word {i}", c.idx);
        }
    }
}

// Checked adapters for the unchanged replay oracle, not native exception proof.
unsafe extern "C" fn checked_render_dev_set_scene_node(
    _render_dev: *mut c_void,
    _frame: *mut c_void,
) -> i32 {
    unsafe {
        record_set_scene(_render_dev, _frame);
    }
    0
}

unsafe extern "C" fn replay_compute_render_size(frame: *mut c_void) -> i32 {
    let svc = services();
    unsafe { hp2_engine::camera::compute_render_size(&svc, frame.cast()) }
        .map_or_else(|status| -status, |()| 0)
}
